static void test_floor(unsigned samples,unsigned posts,unsigned shape,bool active){
    vorbis_info_floor1 info;vorbis_look_floor1 look;float mask[128],mdct[128],saved[128];
    memset(&info,0,sizeof(info));memset(&look,0,sizeof(look));memset(test_arena,0x5a,sizeof(test_arena));
