    for(unsigned step=samples/2;step && next<posts;step/=2)
        for(unsigned x=step;x<samples && next<posts;x+=step*2)info.postlist[next++]=x;
    check_test(next==posts);
    for(unsigned i=0;i<posts;++i)look.forward_index[i]=i;
    for(unsigned a=0;a<posts;++a)for(unsigned b=a+1;b<posts;++b)
