        }
    for(unsigned k=0;k<posts;++k){look.sorted_index[k]=info.postlist[look.forward_index[k]];look.reverse_index[look.forward_index[k]]=k;}
    for(unsigned p=2;p<posts;++p){
        int low=0,high=1;
        for(unsigned q=2;q<p;++q){if(info.postlist[q]<info.postlist[p] && info.postlist[q]>info.postlist[low])low=q;
            if(info.postlist[q]>info.postlist[p] && info.postlist[q]<info.postlist[high])high=q;}
        look.loneighbor[p-2]=low;look.hineighbor[p-2]=high;
    }
