        if(shape==0)mask[z]=-64.0f;
        else if(shape==1)mask[z]=0.0f;
        else if(shape==2)mask[z]=-140.0f;
        else if(shape==3)mask[z]=-128.0f+(float)z*0.5f;
        else mask[z]=z<samples/2?-64.0f:-32.0f;
        mdct[z]=mask[z]-(active?0.0f:16.0f);saved[z]=mask[z];
    }
