    check_test(test_arena[0]==0x5a5a5a5a && test_arena[66]==0x5a5a5a5a);
    if(!active || shape==2){check_test(output==0 && test_allocations==0);return;}
    check_test(output==test_arena+1 && test_allocations==1 && test_requested==(long)(posts*sizeof(int)));
    check_test(output[0]>=0 && output[0]<=1023 && output[1]>=0 && output[1]<=1023);
    for(unsigned r=2;r<posts;++r)check_test((output[r]&0x7fff)<=1023 && !(output[r]&~0xffff));
    if(shape<2){int expected=shape==0?555:1023;check_test(output[0]==expected && output[1]==expected);
        for(unsigned r=2;r<posts;++r)check_test(output[r]==(expected|0x8000));}
    if(shape==3){
        double sx=0.0,sy=0.0,sxx=0.0,sxy=0.0;
        for(unsigned r=0;r<samples;++r){int y=(int)(mask[r]*7.3142857f+1023.5f);sx+=r;sy+=y;sxx+=r*r;sxy+=r*y;}
